+// API keys, roles and the audit log. Keys live in the data (`apiKeys`); an
+// audit entry names the key but never holds the key itself.
+import { AppError } from "../errors.js";
+
+const ACCESS = {
+  read: ["viewer", "cook", "manager"],
+  cook: ["cook", "manager"],
+  manage: ["manager"],
+};
+
+/** The API key record for a token; throws `unauthorized` when there is none. */
+export function authenticate(store, token) {
+  const apiKey = token ? store.data.apiKeys.find((k) => k.key === token) : null;
+  if (!apiKey) throw new AppError("unauthorized");
+  return apiKey;
+}
+
+/** Throws `forbidden` unless the key's role has the access level (read, cook, manage). */
+export function authorize(apiKey, level) {
+  if (!ACCESS[level].includes(apiKey.role)) throw new AppError("forbidden");
+}
+
+/** Appends an audit entry for a request that changed data. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].sort((a, b) => b.id - a.id);
+}
